1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/url"
8		"os"
9		"os/exec"
10		"path/filepath"
11		"strconv"
12		"strings"
13	
14		"github.com/entireio/entire-brain/internal/cli/internal/base"
15		"github.com/spf13/cobra"
16	)
17	
18	type addFlags struct {
19		dir             string
20		build           bool
21		checkpointLimit int
22	}
23	
24	func newAddCommand(opts Options) *cobra.Command {
25		var flags addFlags
26		cmd := &cobra.Command{
27			Use:   "add <repo-url>",
28			Short: "Clone a repository, fetch its Entire history, and build its brain",
29			Long: `add readies a repository for exploration without a manual clone: it clones the
30	repository, fetches its Entire checkpoint history (refs/heads/entire/*), and
31	builds the brain by running ` + "`refresh`" + ` against the clone. Afterward explore it
32	with ` + "`entire brain dash`" + `, ` + "`status`" + `, or ` + "`search`" + ` from inside the clone.`,
33			Args: cobra.ExactArgs(1),
34			RunE: func(cmd *cobra.Command, args []string) error {
35				return runBrainAdd(cmd, opts, flags, args[0])
36			},
37		}
38		cmd.Flags().StringVar(&flags.dir, "dir", ".", "Directory to clone the repository into")
39		cmd.Flags().BoolVar(&flags.build, "build", true, "Build the brain after cloning (use --build=false to clone only)")
40		cmd.Flags().IntVar(&flags.checkpointLimit, "checkpoint-limit", 0, "Limit checkpoints scanned when building the brain (0 = refresh default)")
41		return cmd
42	}
43	
44	func runBrainAdd(cmd *cobra.Command, opts Options, flags addFlags, repoURL string) error {
45		ctx := cmd.Context()
46		out := cmd.OutOrStdout()
47		errOut := cmd.ErrOrStderr()
48	
49		name := repoDirName(repoURL)
50		if name == "" || name == "." || name == ".." || strings.ContainsAny(name, `/\`) {
51			return fmt.Errorf("invalid_repo_url: cannot derive a safe directory name from %q", repoURL)
52		}
53		if strings.HasPrefix(repoURL, "-") {
54			return fmt.Errorf("invalid_repo_url: %q must not start with '-'", repoURL)
55		}
56		if base.BrainNoEgressMode() {
57			return fmt.Errorf("no_egress: add requires cloning or fetching repository history; unset ENTIRE_BRAIN_NO_EGRESS to allow it")
58		}
59		dest := filepath.Join(flags.dir, name)
60	
61		// 1. Clone (skip if the checkout already exists).
62		if isGitCheckout(dest) {
63			origin, _, err := opts.Runner.Run(ctx, dest, "git", "remote", "get-url", "origin")
64			if err != nil || !sameCloneOrigin(repoURL, strings.TrimSpace(string(origin))) {
65				return fmt.Errorf("repository_collision: %s already exists with a different or unreadable origin; choose another --dir", dest)
66			}
67			fmt.Fprintf(out, "clone: %s already present, skipping\n", dest)
68		} else {
69			fmt.Fprintf(out, "clone: %s -> %s\n", repoURL, dest)
70			// "--" ends option parsing so a repo URL can never be read as a git flag.
71			if _, stderr, err := opts.Runner.Run(ctx, "", "git", "clone", "--quiet", "--", repoURL, dest); err != nil {
72				return fmt.Errorf("clone_failed: %s", cloneFailureMessage(repoURL, stderr, err))
73			}
74		}
75	
76		// 2. Fetch the Entire checkpoint history (best-effort: a repo may have none).
77		if _, stderr, err := opts.Runner.Run(ctx, dest, "git", "fetch", "--quiet", "origin", "refs/heads/entire/*:refs/heads/entire/*"); err != nil {
78			fmt.Fprintf(errOut, "note: no Entire history fetched (%v): %s\n", err, strings.TrimSpace(string(stderr)))
79		}
80	
81		// An absolute path is needed for the build env (ENTIRE_REPO_ROOT) and the
82		// manual-build guidance; a failure here (e.g. os.Getwd failing) would
83		// otherwise silently produce an empty "ENTIRE_REPO_ROOT=" suggestion.
84		absDest, err := filepath.Abs(dest)
85		if err != nil {
86			return fmt.Errorf("resolve_clone_path: %q: %w", dest, err)
87		}
88	
89		// 3. Build the brain.
90		if !flags.build {
91			fmt.Fprintf(out, "added %s at %s (clone only; build with `ENTIRE_REPO_ROOT=%s "+base.BrainInvocation(os.LookupEnv, "refresh")+"`)\n", name, dest, absDest)
92			return nil
93		}
94		if err := buildClonedBrain(ctx, cmd, flags, absDest); err != nil {
95			// The clone is kept on disk; surface a non-zero exit so scripts/CI don't
96			// treat a failed build as success, with manual-build guidance.
97			fmt.Fprintf(errOut, "cloned to %s, but the brain build failed; build it manually:\n  ENTIRE_REPO_ROOT=%s "+base.BrainInvocation(os.LookupEnv, "refresh")+"\n", dest, absDest)
98			return fmt.Errorf("brain_build_failed: %w", err)
99		}
100		fmt.Fprintf(out, "added %s at %s — brain built. Explore it with `"+base.BrainInvocation(os.LookupEnv, "dash")+"` (or `status`) from %s.\n", name, dest, dest)
101		return nil
102	}
103	
104	// cloneFailureMessage reduces a failed `git clone` to one human-readable line.
105	// The runner error already embeds the git argv and stderr, so formatting it
106	// verbatim dumped the argv and printed stderr twice (COR-2206); the message is
107	// built from stderr alone, falling back to the root cause when stderr is empty.
108	func cloneFailureMessage(repoURL string, stderr []byte, err error) string {
109		lower := strings.ToLower(string(stderr))
110		// Only genuine repo-missing or auth-denied signals classify. "repository ...
111		// not found" covers git's own fatal line, which quotes the URL between the
112		// two words; both words must sit on ONE line, or unrelated lines combine
113		// (e.g. "git-upload-pack: command not found" plus the "Could not read from
114		// remote repository." footer). "permission denied (publickey" is SSH auth
115		// specifically — bare "permission denied" also appears in local failures
116		// (e.g. creating the work tree dir), and git's "correct access rights"
117		// footer accompanies most SSH transport failures (host key, connection
118		// refused), so neither classifies.
119		repoNotFound := false
120		for _, line := range strings.Split(lower, "\n") {
121			if strings.Contains(line, "repository") && strings.Contains(line, "not found") {
122				repoNotFound = true
123				break
124			}
125		}
126		notFoundOrNoAccess := repoNotFound ||
127			strings.Contains(lower, "authentication failed") ||
128			strings.Contains(lower, "could not read username") ||
129			strings.Contains(lower, "permission denied (publickey")
130		if notFoundOrNoAccess {
131			return repoURL + ": repository not found (or no access)"
132		}
133		seen := map[string]bool{}
134		var lines, specific []string
135		for _, line := range strings.Split(strings.TrimSpace(string(stderr)), "\n") {
136			line = strings.TrimSpace(line)
137			if line == "" || seen[line] {
138				continue
139			}
140			seen[line] = true
141			lines = append(lines, line)
142			if !genericCloneFooterLine(line) {
143				specific = append(specific, line)
144			}
145		}
146		// Prefer the cause-bearing lines; the footer only survives when it is all
147		// git printed.
148		if len(specific) > 0 {
149			lines = specific
150		}
151		if len(lines) == 0 {
152			// The runner wraps the exec error under argv-bearing text; unwrap to the
153			// root (e.g. "exit status 128") to keep the argv off the human surface.
154			for root := errors.Unwrap(err); root != nil; root = errors.Unwrap(root) {
155				err = root
156			}
157			return fmt.Sprintf("%s: %v", repoURL, err)
158		}
159		return repoURL + ": " + strings.Join(lines, "; ")
160	}
161	
162	// genericCloneFooterLine reports whether a stderr line is part of the advice
163	// footer git appends to most SSH transport failures. The footer carries no
164	// cause, so it must not crowd out the specific error line above it.
165	func genericCloneFooterLine(line string) bool {
166		lower := strings.ToLower(line)
167		return strings.Contains(lower, "make sure you have the correct access rights") ||
168			strings.Contains(lower, "and the repository exists") ||
169			strings.Contains(lower, "could not read from remote repository")
170	}
171	
172	// buildClonedBrain builds the cloned repo's brain by running `refresh` with the
173	// repo root pointed at the clone. It re-execs this binary so the refresh runs
174	// with exactly the same defaults as a normal `entire brain refresh` (the refresh
175	// stages shell the host `entire` CLI, which must be on PATH).
176	func buildClonedBrain(ctx context.Context, cmd *cobra.Command, flags addFlags, repoDir string) error {
177		self, err := os.Executable()
178		if err != nil {
179			return fmt.Errorf("locate self: %w", err)
180		}
181		args := []string{"refresh"}
182		if flags.checkpointLimit > 0 {
183			args = append(args, "--checkpoint-limit", strconv.Itoa(flags.checkpointLimit))
184		}
185		c := exec.CommandContext(ctx, self, args...)
186		c.Dir = repoDir
187		c.Env = append(os.Environ(), "ENTIRE_REPO_ROOT="+repoDir)
188		c.Stdout = cmd.OutOrStdout()
189		c.Stderr = cmd.ErrOrStderr()
190		return c.Run()
191	}
192	
193	// repoDirName derives a local directory name from a repo URL, preferring
194	// "<owner>_<repo>". It handles https and scp-like (git@host:owner/repo) URLs and
195	// strips a trailing .git.
196	func repoDirName(repoURL string) string {
197		u := strings.TrimSuffix(strings.TrimSpace(repoURL), "/")
198		u = strings.TrimSuffix(u, ".git")
199		if i := strings.Index(u, "://"); i >= 0 {
200			rest := u[i+3:]
201			if s := strings.IndexByte(rest, '/'); s >= 0 {
202				u = rest[s+1:] // drop host
203			} else {
204				u = rest
205			}
206		} else if i := strings.LastIndex(u, ":"); i >= 0 {
207			u = u[i+1:] // scp-like git@host:owner/repo
208		}
209		parts := make([]string, 0, 3)
210		for _, p := range strings.Split(u, "/") {
211			if p != "" {
212				parts = append(parts, p)
213			}
214		}
215		switch {
216		case len(parts) >= 2:
217			return parts[len(parts)-2] + "_" + parts[len(parts)-1]
218		case len(parts) == 1:
219			return parts[0]
220		default:
221			return ""
222		}
223	}
224	
225	// isGitCheckout reports whether dir already holds a git checkout.
226	func isGitCheckout(dir string) bool {
227		info, err := os.Stat(filepath.Join(dir, ".git"))
