49		dir := t.TempDir()
50		if err := runBrainAdd(newAddTestCmd(), opts, addFlags{dir: dir, build: false}, "https://github.com/acme/widget"); err != nil {
51			t.Fatal(err)
52		}
53		if len(rr.calls) == 0 {
54			t.Fatal("expected a git clone call")
55		}
