146	func TestRunBrainAddCloneFailureIsOneCleanLine(t *testing.T) {
147		const repo = "https://github.com/sandbox-audit/nonexistent-repo.git"
148		for _, tc := range []struct {
149			name, stderr, want string
150		}{
151			{
152				name:   "github-not-found",
153				stderr: "remote: Repository not found.\nfatal: repository 'https://github.com/sandbox-audit/nonexistent-repo.git/' not found\n",
154				want:   "clone_failed: " + repo + ": repository not found (or no access)",
155			},
156			{
157				name:   "git-fatal-only",
158				stderr: "fatal: repository 'https://github.com/sandbox-audit/nonexistent-repo.git/' not found\n",
159				want:   "clone_failed: " + repo + ": repository not found (or no access)",
160			},
161			{
162				name:   "ssh-no-access",
163				stderr: "Permission denied (publickey).\nfatal: Could not read from remote repository.\n",
164				want:   "clone_failed: " + repo + ": repository not found (or no access)",
165			},
166			{
167				name:   "host-key-verification-shows-real-cause",
168				stderr: "Host key verification failed.\nfatal: Could not read from remote repository.\n\nPlease make sure you have the correct access rights\nand the repository exists.\n",
169				want:   "clone_failed: " + repo + ": Host key verification failed.",
170			},
171			{
172				name:   "connection-refused-shows-real-cause",
173				stderr: "ssh: connect to host github.com port 22: Connection refused\nfatal: Could not read from remote repository.\n\nPlease make sure you have the correct access rights\nand the repository exists.\n",
174				want:   "clone_failed: " + repo + ": ssh: connect to host github.com port 22: Connection refused",
175			},
176			{
177				name:   "local-permission-denied-is-not-no-access",
178				stderr: "fatal: could not create work tree dir 'sandbox-audit_nonexistent-repo': Permission denied\n",
179				want:   "clone_failed: " + repo + ": fatal: could not create work tree dir 'sandbox-audit_nonexistent-repo': Permission denied",
180			},
181			{
182				name:   "upload-pack-missing-is-not-not-found",
183				stderr: "bash: git-upload-pack: command not found\nfatal: Could not read from remote repository.\n\nPlease make sure you have the correct access rights\nand the repository exists.\n",
184				want:   "clone_failed: " + repo + ": bash: git-upload-pack: command not found",
185			},
186			{
187				name:   "footer-only-survives",
188				stderr: "fatal: Could not read from remote repository.\n\nPlease make sure you have the correct access rights\nand the repository exists.\n",
189				want:   "clone_failed: " + repo + ": fatal: Could not read from remote repository.; Please make sure you have the correct access rights; and the repository exists.",
190			},
191			{
192				name:   "other-failure-deduplicated",
193				stderr: "fatal: unable to access: Could not resolve host: github.com\nfatal: unable to access: Could not resolve host: github.com\n",
194				want:   "clone_failed: " + repo + ": fatal: unable to access: Could not resolve host: github.com",
195			},
196			{
197				name:   "empty-stderr-falls-back-to-root-cause",
198				stderr: "",
199				want:   "clone_failed: " + repo + ": exit status 128",
200			},
201		} {
202			t.Run(tc.name, func(t *testing.T) {
203				err := runBrainAdd(newAddTestCmd(), Options{Runner: &cloneFailRunner{stderr: tc.stderr}}, addFlags{dir: t.TempDir(), build: false}, repo)
204				if err == nil {
205					t.Fatal("expected a clone failure")
206				}
207				if err.Error() != tc.want {
208					t.Errorf("error = %q, want %q", err, tc.want)
209				}
210				if strings.Contains(err.Error(), "\n") || strings.Contains(err.Error(), "[") {
211					t.Errorf("error must be one line without git argv: %q", err)
212				}
213			})
214		}
215	}
